def inverse_private_standard95(text, workflow):
    if workflow == 'preflight.yml':
        if 'runtime_windows_private_standard95' in text or 'capture-private-standard95-state.py' in text:
            raise AssertionError('Private Windows95 caller moved into preflight')
        return text
    if workflow != 'build.yml': raise AssertionError('Unknown private Windows95 workflow')
    digest=hashlib.sha256(text.encode()).hexdigest()
    if digest == NORMAL_WORKFLOW_SHA256: return text
    if digest != PRIVATE_WORKFLOW_SHA256: raise AssertionError('Complete private Windows95 workflow profile drift')
    for old,new in reversed(EDITS):
        if text.count(new)!=1: raise AssertionError('Private Windows95 exact hunk differs')
        text=text.replace(new,old,1)
    if hashlib.sha256(text.encode()).hexdigest()!=NORMAL_WORKFLOW_SHA256:
        raise AssertionError('Private Windows95 whole inverse differs')
    return text
